class Base {
public:
    // Virtual functions initiate the VTABLE structure
    virtual void common_call() {} 
    virtual void base_only() {}
};

class Derived : public Base {
public:
    // Overriding changes the VTABLE entry for common_call
    void common_call() override {}
};

// Runtime Dispatch
Derived d;
// Base pointer holds derived object's VTABLE pointer (vptr)
Base* ptr = &d; 

// Dynamic Dispatch: calls Derived::common_call via vptr lookup
ptr->common_call(); 

// Dynamic Dispatch: calls Base::base_only (inherited vtable entry)
ptr->base_only();

// Static Dispatch (known at compile time)
// d.base_only();
// ptr->Base::base_only();
